"use client";

import {
  type ChangeEvent,
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { Input } from "./components/ui/input";
import { drawCaptcha } from "./draw";
import {
  defaultIdleHint,
  generateCaptcha,
  inputSanitizePattern,
  normalizeCaptchaLength,
  resolveCharsetMode,
  verifyCaptcha,
} from "./generate";
import { cn } from "./lib/utils";
import type {
  CaptchaHandle,
  CaptchaProps,
  CaptchaStatus,
  CaptchaTheme,
} from "./types";

const DEFAULT_MESSAGES = {
  placeholder: "Type the characters above",
  validHint: "Verified",
  invalidHint: "Incorrect — refresh for a new challenge",
  refreshLabel: "Generate new captcha",
} as const;

function resolveTheme(theme: CaptchaTheme): "light" | "dark" {
  if (theme === "light" || theme === "dark") return theme;
  if (typeof window === "undefined") return "light";
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light";
}

function RefreshIcon({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      width="15"
      height="15"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8" />
      <path d="M21 3v5h-5" />
      <path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16" />
      <path d="M8 16H3v5" />
    </svg>
  );
}

export const Captcha = forwardRef<CaptchaHandle, CaptchaProps>(function Captcha(
  {
    length: lengthProp,
    chars,
    charsetMode: charsetModeProp = "both",
    caseSensitive: caseSensitiveProp = true,
    requireDigit,
    requireUpper,
    requireLower,
    charset,
    width = 210,
    height = 62,
    theme = "system",
    noise = 0.7,
    onVerified,
    onChange,
    onStatusChange,
    onRefresh,
    value: valueProp,
    defaultValue = "",
    disabled = false,
    autoFocus = false,
    id: idProp,
    name,
    showRefresh = true,
    showCounter = true,
    showStatus = true,
    messages: messagesProp,
    className,
    canvasClassName,
    inputClassName,
    refreshClassName,
    inputProps,
  },
  ref,
) {
  const length = normalizeCaptchaLength(chars ?? lengthProp);
  const charsetMode = resolveCharsetMode(charsetModeProp);
  const caseSensitive = charsetMode === "numbers" ? false : caseSensitiveProp;

  const reactId = useId();
  const inputId = idProp ?? `itzsa-captcha-${reactId}`;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const challengeRef = useRef("");
  const onVerifiedRef = useRef(onVerified);
  const onChangeRef = useRef(onChange);
  const onStatusChangeRef = useRef(onStatusChange);
  const onRefreshRef = useRef(onRefresh);

  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const isControlled = valueProp !== undefined;
  const inputVal = isControlled ? valueProp : uncontrolled;
  const [status, setStatus] = useState<CaptchaStatus>("idle");

  const messages = {
    ...DEFAULT_MESSAGES,
    idleHint: defaultIdleHint(charsetMode),
    ...messagesProp,
  };

  useEffect(() => {
    onVerifiedRef.current = onVerified;
    onChangeRef.current = onChange;
    onStatusChangeRef.current = onStatusChange;
    onRefreshRef.current = onRefresh;
  }, [onVerified, onChange, onStatusChange, onRefresh]);

  const setStatusSafe = useCallback((next: CaptchaStatus) => {
    setStatus((prev) => {
      if (prev !== next) onStatusChangeRef.current?.(next);
      return next;
    });
  }, []);

  const paint = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !challengeRef.current) return;
    drawCaptcha(canvas, challengeRef.current, {
      theme: resolveTheme(theme),
      noise,
    });
  }, [theme, noise]);

  const refresh = useCallback(() => {
    challengeRef.current = generateCaptcha({
      length,
      charsetMode,
      requireDigit,
      requireUpper,
      requireLower,
      charset,
    });
    paint();
    if (!isControlled) setUncontrolled("");
    onChangeRef.current?.("");
    setStatusSafe("idle");
    onVerifiedRef.current?.(false);
    onRefreshRef.current?.();
  }, [
    length,
    charsetMode,
    requireDigit,
    requireUpper,
    requireLower,
    charset,
    paint,
    isControlled,
    setStatusSafe,
  ]);

  const reset = useCallback(() => {
    if (!isControlled) setUncontrolled("");
    onChangeRef.current?.("");
    setStatusSafe("idle");
    onVerifiedRef.current?.(false);
  }, [isControlled, setStatusSafe]);

  const validate = useCallback(() => {
    return verifyCaptcha(inputVal, challengeRef.current, caseSensitive);
  }, [inputVal, caseSensitive]);

  useImperativeHandle(
    ref,
    () => ({
      refresh,
      reset,
      getValue: () => inputVal,
      validate,
      getStatus: () => status,
    }),
    [refresh, reset, inputVal, validate, status],
  );

  useLayoutEffect(() => {
    challengeRef.current = generateCaptcha({
      length,
      charsetMode,
      requireDigit,
      requireUpper,
      requireLower,
      charset,
    });
    const canvas = canvasRef.current;
    if (canvas && challengeRef.current) {
      drawCaptcha(canvas, challengeRef.current, {
        theme: resolveTheme(theme),
        noise,
      });
    }
    if (!isControlled) setUncontrolled("");
    setStatusSafe("idle");
    onVerifiedRef.current?.(false);
    // theme/noise only affect paint — see effect below
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    length,
    charsetMode,
    requireDigit,
    requireUpper,
    requireLower,
    charset,
    isControlled,
    setStatusSafe,
  ]);

  useEffect(() => {
    paint();
  }, [paint]);

  useEffect(() => {
    if (theme !== "system" || typeof window === "undefined") return;
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChangeTheme = () => paint();
    mq.addEventListener("change", onChangeTheme);
    return () => mq.removeEventListener("change", onChangeTheme);
  }, [theme, paint]);

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const sanitized = e.target.value
      .replace(inputSanitizePattern(charsetMode), "")
      .slice(0, length);
    if (!isControlled) setUncontrolled(sanitized);
    onChangeRef.current?.(sanitized);

    if (sanitized.length < length) {
      setStatusSafe("idle");
      onVerifiedRef.current?.(false);
      return;
    }

    const valid = verifyCaptcha(sanitized, challengeRef.current, caseSensitive);
    setStatusSafe(valid ? "valid" : "invalid");
    onVerifiedRef.current?.(valid);
  };

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
      data-itzsa-captcha=""
      data-status={status}
      data-charset-mode={charsetMode}
      data-length={length}
    >
      <div className="flex items-center gap-2">
        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className={cn(
            "select-none rounded-md border border-border",
            canvasClassName,
          )}
          aria-hidden
        />
        {showRefresh ? (
          <button
            type="button"
            onClick={refresh}
            disabled={disabled}
            className={cn(
              "inline-flex size-9 shrink-0 items-center justify-center rounded-md border border-border text-secondary transition-colors hover:bg-muted hover:text-primary disabled:opacity-50",
              refreshClassName,
            )}
            title={messages.refreshLabel}
            aria-label={messages.refreshLabel}
          >
            <RefreshIcon />
          </button>
        ) : null}
      </div>

      <Input
        id={inputId}
        name={name}
        type="text"
        value={inputVal}
        onChange={handleChange}
        maxLength={length}
        disabled={disabled}
        autoFocus={autoFocus}
        autoComplete="off"
        autoCorrect="off"
        autoCapitalize="none"
        spellCheck={false}
        placeholder={messages.placeholder}
        aria-label={messages.placeholder}
        aria-invalid={status === "invalid" || undefined}
        className={cn(
          "tracking-[0.3em]",
          "placeholder:tracking-normal",
          status === "valid" &&
            "border-green-600 focus-visible:ring-green-600/30",
          status === "invalid" &&
            "border-red-500 focus-visible:ring-red-500/30",
          inputClassName,
        )}
        {...inputProps}
      />

      {showStatus || showCounter ? (
        <div className="flex items-center justify-between gap-2">
          {showStatus ? (
            <p className="text-xs text-secondary" aria-live="polite">
              {status === "idle" && messages.idleHint}
              {status === "valid" && (
                <span className="text-green-600">{messages.validHint}</span>
              )}
              {status === "invalid" && (
                <span className="text-red-500">{messages.invalidHint}</span>
              )}
            </p>
          ) : (
            <span />
          )}
          {showCounter ? (
            <p className="tabular-nums text-xs text-secondary">
              {inputVal.length}/{length}
            </p>
          ) : null}
        </div>
      ) : null}
    </div>
  );
});

import type * as React from "react";

import { cn } from "../../lib/utils";

/**
 * Lightweight input primitive — ships under `components/itzsa/captcha/components/ui`
 * when installed from the registry (same role as shadcn `components/ui`).
 */
function Input({ className, type, ...props }: React.ComponentProps<"input">) {
  return (
    <input
      type={type}
      data-slot="input"
      data-itzsa-captcha-input=""
      className={cn(
        "flex h-10 w-full min-w-0 rounded-md border border-border bg-transparent px-3 py-1 text-sm text-primary shadow-xs outline-none transition-[color,box-shadow]",
        "placeholder:text-secondary/50",
        "focus-visible:border-accent focus-visible:ring-[3px] focus-visible:ring-accent/30",
        "aria-invalid:border-red-500 aria-invalid:ring-red-500/20",
        "disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
      {...props}
    />
  );
}

export { Input };

import { DIGITS } from "./generate";
import type { CaptchaDrawOptions } from "./types";

function clamp01(n: number) {
  return Math.min(1, Math.max(0, n));
}

function applyPixelNoise(
  ctx: CanvasRenderingContext2D,
  W: number,
  H: number,
  intensity: number,
) {
  const imageData = ctx.getImageData(0, 0, W, H);
  const data = imageData.data;
  const amp = 45 * intensity;

  for (let i = 0; i < data.length; i += 4) {
    const noise = (Math.random() + Math.random() + Math.random() - 1.5) * amp;
    data[i] = Math.min(255, Math.max(0, data[i]! + noise));
    data[i + 1] = Math.min(255, Math.max(0, data[i + 1]! + noise));
    data[i + 2] = Math.min(255, Math.max(0, data[i + 2]! + noise));
  }

  const saltCount = W * H * 0.025 * intensity;
  for (let i = 0; i < saltCount; i++) {
    const px = Math.floor(Math.random() * W);
    const py = Math.floor(Math.random() * H);
    const idx = (py * W + px) * 4;
    const val = Math.random() > 0.5 ? 255 : 0;
    data[idx] = data[idx + 1] = data[idx + 2] = val;
  }

  ctx.putImageData(imageData, 0, 0);
}

function applyBlockPixelation(
  ctx: CanvasRenderingContext2D,
  W: number,
  H: number,
  intensity: number,
) {
  const blockSize = 3;
  const imageData = ctx.getImageData(0, 0, W, H);
  const data = imageData.data;
  const attempts = Math.round(120 * intensity);

  for (let attempt = 0; attempt < attempts; attempt++) {
    const bx = Math.floor(Math.random() * Math.max(1, W - blockSize));
    const by = Math.floor(Math.random() * Math.max(1, H - blockSize));
    let r = 0;
    let g = 0;
    let b = 0;
    let count = 0;
    for (let dy = 0; dy < blockSize; dy++) {
      for (let dx = 0; dx < blockSize; dx++) {
        const idx = ((by + dy) * W + (bx + dx)) * 4;
        r += data[idx]!;
        g += data[idx + 1]!;
        b += data[idx + 2]!;
        count++;
      }
    }
    r /= count;
    g /= count;
    b /= count;
    for (let dy = 0; dy < blockSize; dy++) {
      for (let dx = 0; dx < blockSize; dx++) {
        const idx = ((by + dy) * W + (bx + dx)) * 4;
        const jitter = (Math.random() - 0.5) * 15 * intensity;
        data[idx] = Math.min(255, Math.max(0, r + jitter));
        data[idx + 1] = Math.min(255, Math.max(0, g + jitter));
        data[idx + 2] = Math.min(255, Math.max(0, b + jitter));
      }
    }
  }
  ctx.putImageData(imageData, 0, 0);
}

/**
 * Paint a challenge onto a canvas. Pure (aside from Math.random / matchMedia).
 */
export function drawCaptcha(
  canvas: HTMLCanvasElement,
  text: string,
  options: CaptchaDrawOptions = {},
) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  const W = canvas.width;
  const H = canvas.height;
  const intensity = clamp01(options.noise ?? 0.7);
  const isDark =
    options.theme === "dark"
      ? true
      : options.theme === "light"
        ? false
        : typeof window !== "undefined" &&
          window.matchMedia("(prefers-color-scheme: dark)").matches;

  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = isDark ? "#18181b" : "#f0f0ee";
  ctx.fillRect(0, 0, W, H);

  const grain = W * H * 0.4 * intensity;
  for (let i = 0; i < grain; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const alpha = 0.03 + Math.random() * 0.07;
    ctx.fillStyle = isDark
      ? `rgba(255,255,255,${alpha})`
      : `rgba(0,0,0,${alpha})`;
    ctx.fillRect(x, y, 1, 1);
  }

  for (let y = 0; y < H; y += 2 + Math.floor(Math.random() * 3)) {
    ctx.strokeStyle = isDark
      ? `rgba(255,255,255,${0.03 + Math.random() * 0.05})`
      : `rgba(0,0,0,${0.04 + Math.random() * 0.06})`;
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.stroke();
  }

  const curves = Math.round(6 * intensity);
  for (let i = 0; i < curves; i++) {
    ctx.strokeStyle = isDark
      ? `rgba(255,255,255,${0.12 + Math.random() * 0.15})`
      : `rgba(0,0,0,${0.1 + Math.random() * 0.14})`;
    ctx.lineWidth = 1.2 + Math.random() * 1.8;
    ctx.beginPath();
    ctx.moveTo(Math.random() * W, Math.random() * H);
    ctx.bezierCurveTo(
      Math.random() * W,
      Math.random() * H,
      Math.random() * W,
      Math.random() * H,
      Math.random() * W,
      Math.random() * H,
    );
    ctx.stroke();
  }

  const length = text.length || 1;
  const slotW = W / length;
  const letterColors = isDark
    ? ["#93c5fd", "#86efac", "#fde68a", "#c4b5fd", "#a5f3fc"]
    : ["#1d4ed8", "#15803d", "#b45309", "#6d28d9", "#0e7490"];
  const digitColors = isDark
    ? ["#fb923c", "#f87171", "#e879f9"]
    : ["#c2410c", "#b91c1c", "#86198f"];

  for (let i = 0; i < length; i++) {
    const char = text[i]!;
    const isDigit = DIGITS.includes(char);

    ctx.save();
    ctx.translate(
      slotW * i + slotW / 2 + (Math.random() - 0.5) * 5,
      H / 2 + (Math.random() - 0.5) * 8,
    );
    ctx.rotate((Math.random() - 0.5) * 0.55);
    const skew = (Math.random() - 0.5) * 0.25;
    ctx.transform(1, skew, 0, 1, 0, 0);

    const fontSize = Math.max(
      14,
      Math.round(H * 0.37) + Math.floor(Math.random() * 5),
    );
    ctx.font = `bold ${fontSize}px "Courier New", monospace`;
    const colorPool = isDigit ? digitColors : letterColors;
    ctx.fillStyle = colorPool[Math.floor(Math.random() * colorPool.length)]!;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.globalAlpha = 0.92 + Math.random() * 0.08;
    ctx.shadowColor = isDark ? "rgba(0,0,0,0.9)" : "rgba(180,180,180,0.9)";
    ctx.shadowBlur = 4 + Math.random() * 4;
    ctx.shadowOffsetX = (Math.random() - 0.5) * 2;
    ctx.shadowOffsetY = (Math.random() - 0.5) * 2;
    ctx.fillText(char, 0, 0);
    ctx.globalAlpha = 0.15 + Math.random() * 0.15;
    ctx.shadowBlur = 0;
    ctx.fillText(char, (Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    ctx.restore();
  }

  for (let i = 0; i < 3; i++) {
    ctx.strokeStyle = isDark
      ? `rgba(200,200,200,${0.04 + Math.random() * 0.06})`
      : `rgba(60,60,60,${0.04 + Math.random() * 0.06})`;
    ctx.lineWidth = 1 + Math.random();
    ctx.beginPath();
    const y1 = Math.random() * H;
    const y2 = y1 + (Math.random() - 0.5) * H * 0.5;
    ctx.moveTo(0, y1);
    ctx.lineTo(W, y2);
    ctx.stroke();
  }

  if (intensity > 0.05) {
    applyPixelNoise(ctx, W, H, intensity);
    applyBlockPixelation(ctx, W, H, intensity);
  }

  const scatter = W * H * 0.008 * intensity;
  for (let i = 0; i < scatter; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    ctx.fillStyle = isDark
      ? `rgba(255,255,255,${0.1 + Math.random() * 0.2})`
      : `rgba(0,0,0,${0.08 + Math.random() * 0.15})`;
    ctx.fillRect(x, y, 1 + Math.random(), 1 + Math.random());
  }
}

import type { CaptchaCharsetMode, CaptchaGenerateOptions } from "./types";

const ALPHA_UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const ALPHA_LOWER = "abcdefghijklmnopqrstuvwxyz";
const DIGITS = "0123456789";
const LETTERS = ALPHA_UPPER + ALPHA_LOWER;
const DEFAULT_CHARSET = LETTERS + DIGITS;

function pick(pool: string): string {
  return pool[Math.floor(Math.random() * pool.length)] ?? "A";
}

function shuffle<T>(items: T[]): T[] {
  const arr = [...items];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = arr[i]!;
    arr[i] = arr[j]!;
    arr[j] = tmp;
  }
  return arr;
}

export function normalizeCaptchaLength(length?: number): number {
  return Math.max(3, Math.min(16, length ?? 6));
}

export function resolveCharsetMode(
  mode?: CaptchaCharsetMode,
): CaptchaCharsetMode {
  return mode ?? "both";
}

export function charsetForMode(mode: CaptchaCharsetMode): string {
  if (mode === "letters") return LETTERS;
  if (mode === "numbers") return DIGITS;
  return DEFAULT_CHARSET;
}

/** Regex that strips disallowed input characters for a mode. */
export function inputSanitizePattern(mode: CaptchaCharsetMode): RegExp {
  if (mode === "letters") return /[^A-Za-z]/g;
  if (mode === "numbers") return /[^0-9]/g;
  return /[^A-Za-z0-9]/g;
}

export function defaultIdleHint(mode: CaptchaCharsetMode): string {
  if (mode === "letters") return "Letters only — match case exactly as shown";
  if (mode === "numbers") return "Digits only — match exactly as shown";
  return "Letters & numbers — match case exactly as shown";
}

/**
 * Build a challenge string with guaranteed character classes when requested.
 */
export function generateCaptcha(options: CaptchaGenerateOptions = {}): string {
  const length = normalizeCaptchaLength(options.length);
  const mode = resolveCharsetMode(options.charsetMode);
  const charset = options.charset?.length
    ? options.charset
    : charsetForMode(mode);

  let requireDigit: number;
  let requireUpper: number;
  let requireLower: number;

  if (mode === "numbers") {
    requireDigit = options.requireDigit ?? length;
    requireUpper = options.requireUpper ?? 0;
    requireLower = options.requireLower ?? 0;
  } else if (mode === "letters") {
    requireDigit = options.requireDigit ?? 0;
    requireUpper = options.requireUpper ?? Math.min(1, length);
    requireLower = options.requireLower ?? Math.min(1, Math.max(0, length - 1));
  } else {
    requireDigit = options.requireDigit ?? Math.min(2, length);
    requireUpper = options.requireUpper ?? Math.min(1, length);
    requireLower = options.requireLower ?? Math.min(1, length);
  }

  requireDigit = Math.max(0, requireDigit);
  requireUpper = Math.max(0, requireUpper);
  requireLower = Math.max(0, requireLower);

  const picks: string[] = [];
  if (mode !== "letters") {
    for (let i = 0; i < requireDigit; i++) picks.push(pick(DIGITS));
  }
  if (mode !== "numbers") {
    for (let i = 0; i < requireUpper; i++) picks.push(pick(ALPHA_UPPER));
    for (let i = 0; i < requireLower; i++) picks.push(pick(ALPHA_LOWER));
  }

  while (picks.length < length) {
    picks.push(pick(charset));
  }

  return shuffle(picks).slice(0, length).join("");
}

export function verifyCaptcha(
  input: string,
  expected: string,
  caseSensitive = true,
): boolean {
  if (input.length !== expected.length) return false;
  if (caseSensitive) return input === expected;
  return input.toLowerCase() === expected.toLowerCase();
}

export { ALPHA_UPPER, ALPHA_LOWER, DIGITS, LETTERS, DEFAULT_CHARSET };

export { Captcha } from "./captcha";
export { Input } from "./components/ui/input";
export { drawCaptcha } from "./draw";
export {
  ALPHA_LOWER,
  ALPHA_UPPER,
  charsetForMode,
  DEFAULT_CHARSET,
  DIGITS,
  defaultIdleHint,
  generateCaptcha,
  inputSanitizePattern,
  LETTERS,
  normalizeCaptchaLength,
  resolveCharsetMode,
  verifyCaptcha,
} from "./generate";
export { cn } from "./lib/utils";
export type {
  CaptchaCharsetMode,
  CaptchaDrawOptions,
  CaptchaGenerateOptions,
  CaptchaHandle,
  CaptchaMessages,
  CaptchaProps,
  CaptchaStatus,
  CaptchaTheme,
} from "./types";

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type { ComponentProps } from "react";

export type CaptchaStatus = "idle" | "valid" | "invalid";

export type CaptchaTheme = "light" | "dark" | "system";

/**
 * What characters appear in the challenge.
 * - `both` — letters + digits (default)
 * - `letters` — A–Z / a–z only
 * - `numbers` — 0–9 only
 */
export type CaptchaCharsetMode = "both" | "letters" | "numbers";

export type CaptchaMessages = {
  placeholder?: string;
  idleHint?: string;
  validHint?: string;
  invalidHint?: string;
  refreshLabel?: string;
};

export type CaptchaHandle = {
  /** Generate a new challenge and clear the input. */
  refresh: () => void;
  /** Clear input + status without regenerating (same challenge). */
  reset: () => void;
  /** Current user input. */
  getValue: () => string;
  /** Whether the current input matches the challenge. */
  validate: () => boolean;
  /** Latest verification status. */
  getStatus: () => CaptchaStatus;
};

export type CaptchaGenerateOptions = {
  /** Number of characters in the challenge (3–16, default 6). */
  length?: number;
  /** Letters only, numbers only, or both (default). */
  charsetMode?: CaptchaCharsetMode;
  requireDigit?: number;
  requireUpper?: number;
  requireLower?: number;
  /** Override the character pool (skips charsetMode pool when set). */
  charset?: string;
};

export type CaptchaDrawOptions = {
  theme?: Exclude<CaptchaTheme, "system">;
  /** 0 = clean, 1 = max noise (default ~0.7). */
  noise?: number;
};

export type CaptchaProps = {
  /**
   * Number of characters shown in the captcha (3–16).
   * Alias: `chars`.
   * @default 6
   */
  length?: number;
  /** Alias for `length` — number of captcha characters. */
  chars?: number;

  /**
   * Character set for the challenge.
   * @default "both"
   */
  charsetMode?: CaptchaCharsetMode;
  /** Exact string match including case (default true; ignored for numbers-only). */
  caseSensitive?: boolean;
  requireDigit?: number;
  requireUpper?: number;
  requireLower?: number;
  charset?: string;

  /** Canvas width in CSS pixels (default 210). */
  width?: number;
  /** Canvas height in CSS pixels (default 62). */
  height?: number;
  /** Render theme. `system` follows `prefers-color-scheme` (default). */
  theme?: CaptchaTheme;
  /** Noise / interference intensity 0–1 (default 0.7). */
  noise?: number;

  onVerified?: (valid: boolean) => void;
  onChange?: (value: string) => void;
  onStatusChange?: (status: CaptchaStatus) => void;
  onRefresh?: () => void;

  /** Controlled input value. */
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  autoFocus?: boolean;
  id?: string;
  name?: string;

  showRefresh?: boolean;
  showCounter?: boolean;
  showStatus?: boolean;
  messages?: CaptchaMessages;

  className?: string;
  canvasClassName?: string;
  inputClassName?: string;
  refreshClassName?: string;
  /** Extra props forwarded to the text input. */
  inputProps?: Omit<
    ComponentProps<"input">,
    "value" | "onChange" | "disabled" | "maxLength" | "type"
  >;
};
